import xml.etree.ElementTree as ET

def parse_policy(policy_xml):
    root = ET.fromstring(policy_xml)
    principals = {}
    roles = {}

    for principal in root.findall('principal'):
        token = principal.get('token')
        role = principal.get('role')
        if token not in principals:
            principals[token] = []
        principals[token].append(role)

    for role_elem in root.findall('role'):
        role_name = role_elem.get('name')
        allows = []
        for allow_elem in role_elem.findall('allow'):
            path = allow_elem.get('path')
            allows.append(path)
        roles[role_name] = allows

    return principals, roles

def check_access(token, resource_path, principals, roles):
    if token not in principals:
        return False

    for role in principals[token]:
        if role in roles and resource_path in roles[role]:
            return True
    return False

def main():
    if len(sys.argv) != 3:
        sys.exit(0)

    policy_file = sys.argv[1]
    resource_path = sys.argv[2]

    auth_token = os.getenv('AUTH_TOKEN')
    if not auth_token:
        print('DENY')
        sys.exit(0)

    try:
        with open(policy_file, 'r') as f:
            policy_xml = f.read()
    except IOError:
        print('DENY')
        sys.exit(0)

    principals, roles = parse_policy(policy_xml)

    if check_access(auth_token, resource_path, principals, roles):
        print('ALLOW')
    else:
        print('DENY')

if __name__ == '__main__':
    main()

