import argparse
import json
import subprocess
import xml.etree.ElementTree as ET
from pathlib import Path

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.get('id'),
            'command': job_elem.find('command').text
        }
        jobs.append(job)
    return jobs

def process_jobs(jobs, cache_file):
    cache = {}
    if Path(cache_file).exists():
        with open(cache_file, 'r') as f:
            cache = json.load(f)

    executed_jobs = []
    for job in jobs:
        job_id = job['id']
        if job_id not in cache:
            result = subprocess.run(job['command'], shell=True, capture_output=True, text=True)
            cache[job_id] = {
                'stdout': result.stdout,
                'exit_code': result.returncode
            }
            executed_jobs.append((job_id, result.returncode))

    with open(cache_file, 'w') as f:
        json.dump(cache, f, indent=2)

    for job_id, exit_code in executed_jobs:
        print(f"{job_id} {exit_code}")

def main():
    parser = argparse.ArgumentParser(description='Run jobs from XML and cache results in JSON.')
    parser.add_argument('xml_file', help='XML file containing jobs')
    parser.add_argument('json_file', help='JSON file to cache results')
    args = parser.parse_args()

    jobs = parse_xml(args.xml_file)
    process_jobs(jobs, args.json_file)

if __name__ == '__main__':
    main()

import sys
import subprocess
import requests
import re
from typing import Optional, Tuple

def evaluate_expr(expr: str) -> Optional[str]:
    try:
        return str(eval(expr))
    except:
        return ""

def run_cmd(cmd: str) -> Optional[str]:
    try:
        result = subprocess.run(cmd, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout + result.stderr
    except:
        return ""

def fetch_url(url: str) -> Optional[str]:
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except:
        return ""

def render_template(template_path: str) -> str:
    with open(template_path, 'r') as f:
        content = f.read()

    def replace_placeholder(match):
        kind = match.group(1)
        value = match.group(2).strip('"')

        if kind == 'expr':
            return evaluate_expr(value)
        elif kind == 'cmd':
            return run_cmd(value)
        elif kind == 'url':
            return fetch_url(value)
        return ""

    pattern = re.compile(r'\{\{\s*(expr|cmd|url)\s*:\s*(.*?)\s*\}\}')
    return pattern.sub(replace_placeholder, content)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python render.py <template_file>", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    print(render_template(template_path))

