from concurrent.futures import ThreadPoolExecutor, as_completed
import sys

def load_results():
    if os.path.exists("results.jsonl"):
        with open("results.jsonl", "r") as f:
            return [json.loads(line) for line in f]
    return []

def save_results(results):
    with open("results.jsonl", "a") as f:
        for result in results:
            f.write(json.dumps(result) + "\n")

def process_job(job_id, command):
    try:
        process = subprocess.Popen(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate()
        output = stdout + stderr
        exit_code = process.returncode
        return {"id": job_id, "exit_code": exit_code, "output": output}
    except Exception as e:
        return {"id": job_id, "exit_code": -1, "output": str(e)}

def main():
    if len(sys.argv) != 2:
        print("Usage: python jobrunner.py <json_file>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    with open(input_file, "r") as f:
        jobs = json.load(f)

    existing_results = load_results()
    existing_ids = {r["id"] for r in existing_results}

    executed = 0
    skipped = 0
    active_commands = set()

    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = []
        for job in jobs:
            job_id = job["id"]
            if job_id in existing_ids:
                skipped += 1
                continue
            futures.append(executor.submit(process_job, job_id, job["command"]))

        for future in as_completed(futures):
            result = future.result()
            if result["id"] not in active_commands:
                active_commands.add(result["id"])
                save_results([result])
                executed += 1
            else:
                # Handle duplicate submission (shouldn't happen due to existing_ids check)
                pass

