import xml.etree.ElementTree as ET
from typing import List, Dict, Any

def load_xml(url: str) -> List[Dict[str, Any]]:
    try:
        with urllib.request.urlopen(url) as response:
            xml_data = response.read().decode('utf-8')
            root = ET.fromstring(xml_data)
            rules = []
            for rule_elem in root.findall('rule'):
                field = rule_elem.get('field')
                when_expr = rule_elem.find('when')
                expr_elem = rule_elem.find('expr')
                rules.append({
                    'field': field,
                    'when_expr': when_expr.text if when_expr is not None else None,
                    'expr': expr_elem.text
                })
            return rules
    except Exception as e:
        print(f"fetch failed: {url}", file=sys.stderr)
        sys.exit(1)

def load_json(path: str) -> List[Dict[str, Any]]:
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"input failed: {path}", file=sys.stderr)
        sys.exit(1)

def process_items(items: List[Dict[str, Any]], rules: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    processed = []
    for item in items:
        processed_item = item.copy()
        for rule in rules:
            when_active = rule['when_expr'] is None or eval(rule['when_expr'], {}, processed_item)
            if when_active:
                field = rule['field']
                processed_item[field] = eval(rule['expr'], {}, processed_item)
        processed.append(processed_item)
    return processed

def main():
    if len(sys.argv) != 3:
        print("Usage: python apply_rules.py <url> <json_path>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    json_path = sys.argv[2]

    rules = load_xml(url)
    items = load_json(json_path)
    processed_items = process_items(items, rules)

    for item in processed_items:
        print(json.dumps(item))

if __name__ == "__main__":
    main()

