import sys
import xml.etree.ElementTree as ET

class Client:
    def __init__(self, token, jobs, limit):
        self.token = token
        self.jobs = set(jobs.split(','))
        self.limit = limit
        self.ok_count = 0

def load_clients(config_file):
    tree = ET.parse(config_file)
    root = tree.getroot()
    clients = {}
    for client_elem in root.findall('client'):
        token = client_elem.get('token')
        jobs = client_elem.get('jobs')
        limit = int(client_elem.get('limit'))
        clients[token] = Client(token, jobs, limit)
    return clients

def process_requests(clients):
    for line in sys.stdin:
        token, job_name = line.strip().split()
        if token not in clients:
            print('UNKNOWN_TOKEN')
            continue
        client = clients[token]
        if job_name not in client.jobs:
            print('JOB_NOT_ALLOWED')
            continue
        if client.ok_count >= client.limit:
            print('LIMIT_EXCEEDED')
        else:
            print('OK')
            client.ok_count += 1

